 "content": "def transform(grid):
    """Expand the central 2 into diagonal rays, then continue the pattern in 1s."""
    n = len(grid[0])
    if len(grid) != 1 or n % 2 != 1:
        raise ValueError("expected a single odd-width input row")
    center = n // 2
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            out[r][center - r] = 2
            out[r][center + r] = 2
        else:
            for c in range(n):
                if (c - r) % 4 == 2:
                    out[r][c] = 1
    return out
